"geography_and_latency.inside_the_uae_only_the_two":"UAE国内では、免許を持つ2社、Etis-a-lotとDu-opolyだけが光ファイバーを敷設できます。ダークファイバーも自前の掘削もなく、波長は3×の価格です。",
