"geography_and_latency.overland_between_continents_crosses":"大陸間を陸路で結ぶと国境を十いくつも越え、途中のキャリアがそれぞれ取り分を取ります。価格は{x}×。海底のほうがはるかに安上がりです。",
"geography_and_latency.pricey_fewer_carriers":"割高：キャリアが少ない",
"geography_and_latency.this_route_crosses_a_border_in":"このルートはアフリカで国境を越えます：価格は2×。どの国も独自の許認可、独自のキャリア、そして独自の取り分を求めます。",
"geography_and_latency.this_route_crosses_the_andes_2":"このルートはアンデスを越えます：価格は2×。平地のファイバーよりも土砂崩れや雪でずっと頻繁に切れます。",
"geography_and_latency.this_route_crosses_the_nullarbor_x":"このルートはナラボー平原を横断します：価格は{x}×。千キロにわたって何もなく、そのすべてを既存事業者が握っています。",
"geography_and_latency.this_route_goes_into_the_amazon":"このルートはアマゾンに入ります：価格は2×。ファイバーは川沿いやジャングルの道に沿って走り、修理には船で向かいます。",
