"hyper_az.hit_ups":"{city}の{zone}のバッテリー室が、月例テストで本当に故障して不合格になりました。建物1棟がのろのろと再起動し、残りは{p}で稼働を続けています。",
"hyper_az.lead":"ゾーンとは、同じ都市圏内で数km離れた別の建物で、独自の電力系統を持ち、短く太い光ファイバーでつながっています。クラッシュ、停電、操作ミス、証明書切れが起きても、止まるのはその建物のゾーンだけ。リージョンは動き続けます。",
"hyper_az.lesson":"ゾーンは最悪の1日から守ってくれます。リージョンは最悪の1年から守ってくれます。",
"hyper_az.live":"🧱 {city}の{zone}が稼働しました：+{g}、コンピュートスロット+{n}、独自の電力系統付き。",
"hyper_az.not_for":"ゾーンは熱波、エネルギー危機、建設モラトリアム、法規制、リージョン全体の停止には役立ちません。それにはレプリカリージョンが必要です。",
"hyper_az.out_here":"建物1棟が{date}まで停止中：リージョンは{p}で稼働、フェイルオーバーなし。",
"hyper_az.outages":{"one":"ここでのローカル障害：これまでに{n}件。","other":"ここでのローカル障害：これまでに{n}件。"},
"hyper_az.pow_msg":"{util}が{city}の{zone}への給電を失いました。もう一方のゾーンは別系統なので稼働を継続。リージョンは{p}で稼働中。",
"hyper_az.ready_on":"{date}開設",
"hyper_az.soft":"被害は{zone}だけでした。他のゾーンが引き継ぎ、リージョンは{p}で稼働中。フェイルオーバーなし、ほんの一瞬のブレです。",
"hyper_az.started":"🧱 {city}で{zone}を建設中。最初の建物から数km離れた、独自の電力系統です。{date}に稼働開始。",
