"hyper_dir.held":"🧊 {city}はレンタル機材で夜を乗り切りました。{util}からよろしくとのことです。",
"hyper_dir.intro_ai":"🧠 <b>AIラボに目をつけられました。</b>2つのリージョン間で何週間もの学習を回したいそうです。期限内なら数百万、遅れたら半額です。",
"hyper_dir.intro_ddos":"🧨 <b>ボットネットにアドレスを知られました。</b>ときどき誰かがテナントを攻撃してきます。余裕のあるポートと太いバックボーンで吸収しましょう。",
"hyper_dir.intro_fail":"🦍 <b>リージョンが2つになったので、リージョン丸ごとの障害もあり得ます。</b>そのユーザーはレプリカへ移ります。バックログを少なく、バックボーンを太く保ちましょう。ここが本番の試験です。",
"hyper_dir.intro_freeze":"🎮 <b>ゲームスタジオがローンチを計画中です。</b>ローンチ日にはトラフィックが何倍にもなり、ネットワークは変更凍結。凍結前に増強しておきましょう。",
"hyper_dir.intro_inc":"☁️ <b>クラウドならではの壊れ方をする規模になりました。</b>証明書切れ、レプリケーションストーム、ドットが1つ抜けたRoute 66。どれにも修理ボタンが付いています。",
"hyper_dir.intro_law":"🏛️ <b>規制当局がクラウドの存在に気づきました。</b>法律には猶予期間があります。求められた場所に建てるか、罰金を払うかです。",
"hyper_dir.intro_pev":"⚡ <b>電力にも機嫌があります。</b>熱波やエネルギー危機は大陸全体を襲い、電気代は上がり、冷却装置は汗をかきます。電力網が落ちそうなときは1日前に警告が来ます。",
"hyper_dir.intro_rv":"🥊 <b>ライバルクラウドに目をつけられました。</b>テナントに入札してきたり、契約更新時に不満なテナントを口説いたり、ときには価格戦争を仕掛けてきます。",
