"hyper_dir.warn_heat":"🌡️ {city}はすでに{util}が回せる電力の{p}%を使っていて、熱波のピークは明日です。電力網が落ちてリージョンが停止するかもしれません。今夜のうちに冷却装置をレンタルするか、負荷を移しましょう。",
