"hyper_ops.o_az":"リージョンにゾーンを",
"hyper_ops.o_az_d":"ローカル障害（クラッシュ、停電、建物1棟での操作ミス）に見舞われたリージョンに、レベル・メガワット・法律が許す範囲でアベイラビリティゾーンを追加します。1シフトに1つまで。",
"hyper_ops.o_drill":"フェイルオーバー訓練",
"hyper_ops.o_drill_d":"最後の訓練から一番時間が経ったリージョンペア（未実施のものが最優先）で訓練を行います。一度に1つずつ、ローンチ前の変更凍結の直前には行いません。",
"hyper_ops.o_fund":"抗議に応える",
"hyper_ops.o_fund_d":"地域基金で味方にできる抗議運動には、下の上限額まで、味方になるまで基金を出します。好感度でトラフィックは1ビットも動きません。",
"hyper_ops.o_rg":"リージョンを見守る",
"hyper_ops.o_rg_desc":"しきい値以上のリージョンを1段階上の規模に拡張します。月に1回まで、2レベル前に解放した規模まで、メガワットと法律が許し、その月が黒字のままの場合に限ります。電力が足りなければ、早めに電力会社に申請します。それ以外はレポートに記録します。",
"hyper_ops.o_wave":"バックログ用の波長",
"hyper_ops.o_wave_desc":"レプリケーションのバックログがしきい値を超えて増えたリージョンペアに、足りない分を運べる最小の波長を2リージョン間でリースします。1シフトに1本、その後1週間は解消を待ちます。月額は予算から差し引かれ、その月を赤字にすることはありません。",
