"hyper_reg.cc_ann":"{country}の{min}がデータローカライゼーション法を発表しました。{date}から、現地ユーザーのデータは{country}国内のリージョンに置かなければなりません。期限までに建てないと、ユーザーは待たされ、成長が止まります。",
"hyper_reg.cc_live":"{country}のデータローカライゼーション法が施行されました。{min}は空っぽのラックの前でテープカットをしました。現地のユーザーは国内にリージョンができるのを待っています。",
