"hyper_reg.egr_ann":"{min}があなたのエグレス料金の調査を開始しました（「ホテル・カリフォルニア」：データはチェックインできても、二度と出ていけない）。1年間{p}値下げするか、{date}までに{fee}を支払いましょう。",
"hyper_reg.egr_cut":"{date}までエグレス料金を{p}値下げしました。{min}は「歴史的なチェックアウト」と評しています。ストレージのテナントたちから花が届きました。",
"hyper_reg.egr_cut_btn":"エグレスを{p}値下げ",
