"hyper_reg.egr_pay_btn":"{fee}を支払う",
"hyper_reg.eu_ann_safe":"{min}が規則を強化します。{date}から、EUユーザーのデータをEU域外かつEUが信頼しない国のレプリカへコピーするには、弁護士と移転影響評価が必要になり、リージョンごとに毎月{fee}かかります。EU域内か、EUが信頼する国のレプリカを選びましょう。",
"hyper_reg.eu_live":"EUのデータ移転規則が施行されました。{min}から400ページのガイダンス文書が届きました。300ページの要約付きです。",
"hyper_reg.eu_n_unsafe":{"one":"EUのリージョン1つが、EUが信頼しない国へコピーしています。レプリカを移すまで、弁護士費用が毎月{fee}かかります。","other":"EUのリージョン{n}つが、EUが信頼しない国へコピーしています。レプリカを移すまで、それぞれ弁護士費用が毎月{fee}かかります。"},
"hyper_reg.mor_ann":"{min}が、{date}から{until}まで{city}でのデータセンターの電力網への新規接続を停止します。そこでは新しいリージョンも増強もできず、電力会社は電話に出なくなります。自家発電は引き続き認められます。",
