"hyper_reg.mor_no_zone":"{min}の答えはノー：{until}まで{city}では、ゾーンも含めて新しい建物は一切認めません。ほかの場所に建てましょう。",
"hyper_reg.mor_over":"{city}のモラトリアムが終わりました。電力網への新規接続が再開され、電力会社も電話に出るようになりました。",
"hyper_reg.mor_own_short":"{min}の答えはノー：{until}まで{city}では電力網への新規接続はできません。自家発電の余力は{free} MWで、これには{need} MW必要です。自家発電を増やすか、ほかの場所に建てましょう。",
"hyper_reg.mor_refused":"{min}の答えはノー：{until}まで{city}では電力網への新規接続はできません。ほかの場所に建てるか、自家発電を作りましょう。",
"hyper_reg.pue_ann":"{min}が、{date}から{reg}のデータセンターにエネルギー報告を義務づけると発表しました。熱を捨てているリージョンは、MWあたり毎月{fee}を支払います。排熱を再利用していれば対象外です。",
