"hyper_rivals.war_choice":"対抗する（{date}まで現地のテナントに{p}オフ）か、無視するか。無視すると、現地で更新するテナントは同じ値下げを求め、不満なテナントは去っていきます。",
"hyper_rivals.war_credits":"{rival}が{reg}でクラウド価格を{p}値下げ：「無料クレジットが20%増量！」",
