"hyper_rivals.war_over":"{rival}が{reg}で始めた価格戦争は終わりました。価格は「ただのおかしな値段」に戻りました。",
"hyper_rivals.win_credits":"{rival}は、火曜日に期限が切れる100万ドル分の無料クレジットで{name}と契約しました。",
"hyper_rivals.win_donuts":"あなたがまだ考えている間に、{rival}が{name}と契約しました。向こうの営業はドーナツを持ってきたそうです。",
