"hyper_rivals.you_fit":"あなたの方が条件に合っています：自分の価格で契約できます。",
"hyper_story.charter_desc":"階段下のラック1台から、天気を左右するほどのクラウドへ。各国でローンチし、玄関口を開き、電力のある場所にリージョンを建て、すべてのバイトを自社のバックボーンで運びましょう。テナントは妙な名前のバンドルを借りていきます。トランジットは買っても、決して売りません。勝利条件はCloud Nine：{ct}大陸にリージョン、すべてのリージョンペアで訓練合格、海を越える自社ケーブル、そしてピーク時にリージョン間{g}。",
"hyper_story.eyebrow":"クラウドレベル {lv}/{max}",
"hyper_story.g_done":"クラウドって、つまりこれで全部です。ユーザーが入ってきて、リージョンが応え、リージョン同士が会話する。あとは目標がCloud Nineへ導いてくれます。",
"hyper_story.g_door":"ユーザーには入口が必要です。本拠地のPOPに外への出口（IXポート、PNI、トランジット）を用意すれば、そこが玄関口になります。トランジットは買うだけで、決して売りません。",
"hyper_story.g_drill":"では証明しましょう：フェイルオーバー訓練を実施します。{city}をわざと1日レプリカへ退避させ、誰が気づくか見てみます。",
"hyper_story.g_grow":"時間を進めて、ユーザーが増えるのを眺めましょう。品質が{p}を上回っている限り、増え続けます。",
"hyper_story.g_launch":"あなたのクラウドは階段下のラック1台です。{country}でローンチしましょう。プライバシーポリシーを公開した瞬間にユーザーが登録します（誰も読みません）。",
"hyper_story.g_region":"リージョンが1つだけでは、ロゴが立派な単一障害点です。2つ目として{city}に{name}を{cost}で建てましょう。町は電力についていろいろ言ってくるはずです。",
"hyper_story.g_region_cage":"リージョンが1つだけでは、ロゴが立派な単一障害点です。2つ目を{city}に建てましょう：{name}を{cost}で建てるか、現地の{prov}でケージを{mo}/月で借りて、あとで引っ越すこともできます。",
"hyper_story.g_replica":"2つ目のリージョンが稼働しました。{city}の「クラウド」タブでそれをレプリカに選びましょう。ユーザーが書き込んだデータの約{p}がそこへコピーされ、{city}が落ちたらユーザーはそちらへ移ります。",
"hyper_story.g_tenant":"テナントがクラウド製品のバンドルを持って電話してきています。オファーを受けましょう：稼働中のリージョンに空きコンピュートスロットが必要です。",
"hyper_story.help":"クラウドを築くためのチャーターです。ユーザーは国単位でローンチされ、いちばん近い玄関口から入ってきます。玄関口とは、トランジット、IXポート、PNIのいずれかがあるPOPのこと。そこにエッジスタックがあれば静的な{p}を配信し、残りは本拠地のリージョンから自社バックボーンで運ばれます。レイテンシがそのまま品質です。リージョンには電力が必要で、町はいろいろ言ってきます。各リージョンはレプリカにコピーし、まだコピーされていない分はリージョン障害で失われます。だからフェイルオーバー訓練を。テナントはクラウド製品のバンドルを買い、AIラボはリージョン間で学習ランを借り、エグレスはホテル・カリフォルニア方式の料金です。トランジットは買っても売りません。Tier 1はバッジ、勝利はCloud Nine（{ct}大陸にリージョン、全ペアで訓練、自社の海底ケーブル、リージョン間{g}）。",
"hyper_story.level_up":"<b>レベル{lv}：{name}！</b>解放：{unlock}。",
"hyper_story.lv01":"階段下のラック",
"hyper_story.lv01_q":"「データセンターじゃないよ、野心のある物置だよ。本番環境の近くで掃除機をかけるのはやめてください」— 唯一のエンジニア",
"hyper_story.lv02":"ところにより曇り",
"hyper_story.lv02_q":"「ステータスページは『ところにより曇り』。うちのアプリは『おおむね炎上』です」— 最初の顧客",
"hyper_story.lv03":"雲に覆われて",
"hyper_story.lv03_q":"「今は全部を2つ目のリージョンにレプリケートしています。バグもリアルタイムで」— リードエンジニア",
"hyper_story.lv04":"株式会社積乱雲",
"hyper_story.lv04_q":"「エンジニアにコスト削減案を頼んだら、郵便番号付きのキャンパスが送られてきた」— CFO",
"hyper_story.lv05":"フォグコンピューティング",
"hyper_story.lv05_q":"「省のデータは決して国外に出してはなりません。請求書もです」— 書類省",
"hyper_story.lv06":"エグレス長者",
"hyper_story.lv06_q":"「データは無料でチェックインして、出るときにお金を払う。エグレスをホテル・カリフォルニア方式にした人は昇給に値する」— CFO",
"hyper_story.lv07":"アベイラビリティゾーン・ディフェンス",
"hyper_story.lv07_q":"「アベイラビリティゾーンは3つ、コーヒーマシンは共用で1台。どっちが原因で落ちたと思う？」— オンコール担当エンジニア",
"hyper_story.lv08":"メガワット王",
"hyper_story.lv08_q":"「御社のキャンパスは今や弊社最大の顧客で、最大の悩みの種で、町の温水プールが温かい理由です」— Watt Now Energy",
"hyper_story.lv09":"核分裂、ミッション完了",
"hyper_story.lv09_q":"「大臣が原子炉のテープカットを行います。非常に敬意ある距離から」— エネルギー大臣室",
"hyper_story.lv10":"ジェット気流",
"hyper_story.lv10_q":"「AIチームから『大西洋だけ、6週間』と頼まれた。今度は太平洋も欲しいそうだ」— ネットワークプランナー",
"hyper_story.lv11":"大きすぎてフェイルオーバーできない",
"hyper_story.lv11_q":"「取締役会に『うちは大きすぎて潰せないのか』と聞かれた。いいえ、フェイルオーバーします。ランブック412ページ」— 信頼性責任者",
"hyper_story.lv12":"成層圏",
"hyper_story.lv12_q":"「全部御社のクラウドに移しました。今では御社のリージョンに雨が降ると、うちの株価が濡れます」— とても大きな顧客",
"hyper_story.lv13":"気象システム",
"hyper_story.lv13_q":"「明日の天気予報を聞いたのに。首都にある御社のリージョンこそが予報そのものだ」— ある首相",
"hyper_story.next":{"one":"次：{name}。ピーク{pk}、稼働中のリージョン{n}つで到達。{unlock}が手に入ります。","other":"次：{name}。ピーク{pk}、稼働中のリージョン{n}つで到達。{unlock}が手に入ります。"},
"hyper_story.next_ai":"さらに、ピーク時にリージョン間でAIトラフィック{g}：学習ランとデータレイクを、自社のバックボーンで。",
"hyper_story.next_ct":{"one":"次：{name}。ピーク{pk}、{c}大陸に稼働中のリージョン{n}つで到達。{unlock}が手に入ります。","other":"次：{name}。ピーク{pk}、{c}大陸に稼働中のリージョン{n}つで到達。{unlock}が手に入ります。"},
