"hyper_super.f_stalled":"停滞",
"hyper_super.frontier_flop":"フロンティアモデル{name}は、スーパークラスター全体でデータを{p}しか与えられず、今では月はデータセンターだと言い張っています。マスコミは大喜びです。",
"hyper_super.frontier_go":"フロンティアモデルを学習させる",
"hyper_super.frontier_level":"フロンティアモデルはレベル{lv}から。",
"hyper_super.frontier_offer":"{a}、{b}、{c}にまたがって学習させる自社のフロンティアモデル：2つの区間それぞれに{g}を{n}週間、各区間はレイテンシ上限以内で。学習中はGPUと電力に{mo}/月かかります。",
"hyper_super.frontier_running":"フロンティアモデル{name}：学習{p}、{date}リリース。",
"hyper_super.frontier_shipped":"{name}リリース！フロンティアモデルのおかげで、{date}までユーザーの成長と収益が{p}アップします。",
"hyper_super.frontier_started":"{name}が{a}、{b}、{c}にまたがって学習を開始しました。{date}にリリースされ、どこまで賢くなるかは一番遅い区間次第です。",
"hyper_super.leg_stalled":"停滞中：この区間は{via}経由で{ms} msかかり、上限の{lim} msを超えているため、運んだデータが一切カウントされません。{a}と{b}の間に直結リンクなど、もっと短い経路を作れば動き出します。",
"hyper_super.leg_stalled_short":"停滞：{ms} ms、上限{lim} ms",
"hyper_super.need_trio":"スーパークラスターには、少なくとも2つの大陸にまたがる稼働中のリージョンが3つ必要です。",
"hyper_super.offer":"{lab}が、{a}、{b}、{c}にまたがるスーパークラスターでの{n}週間の学習ランを求めています。オファーはチャーターカードにあります。",
"hyper_super.offer_line":"{lab}：{a}、{b}、{c}にまたがるスーパークラスター。2つの区間それぞれに{g}を{n}週間、各区間{lim}以内、期限内なら{fee}。",
"hyper_super.paid":"{lab}のスーパークラスター学習ランが3リージョンにまたがって期限内に完了し、{fee}が支払われました。どこかのスライドに「惑星規模」と書かれています。",
