"long_tail.the_plus_is_a_usage_fee":"プラスは従量料金のこと。ギガビット単位のペイドピアリングです。",
"long_tail.the_same_phone_company_as_in":"太平洋と同じ電話会社が、海ひとつ隔てたこちらにも。ジャマイカからトリニダードまで、どの島にもSIMカードを。",
"long_tail.the_seychelles_old_telco_open_to":"セーシェルの老舗通信会社。ピアリングには前向きですが、国内にその場所がありません。",
