"long_tail.yee_haw_and_low_earth_orbit":"イーハー！と低軌道。",
"loop.australia_got_more_australian":"<b>オーストラリアがさらにオーストラリアらしくなりました。</b><br>現地のトランジット料金は通常の3倍になり、売っているのはオーストラリアで実際にトランジットを販売するキャリアだけ。TelstrayaとFloptusはプライベートピアリングしかしないので、IXのセッションは終了しました。オーストラリアのPOPを確認してください。",
"loop.new_networks_on_the_map_this":"<b>マップに新しいネットワークが登場。</b><br>今回のアップデートで、まだつながっていないネットワークが追加されました。{n}日間は無料の暫定ルートで届くので、到達範囲が一晩で減ることはありません。終わる前にピアリングするか、トランジットを買いましょう。",
"loop.something_in_the_noc_glitched_the":"<b>NOCで何か不具合が起きました。</b><br>ゲームは続いています。様子がおかしいときは、セーブをエクスポートしてGitHubでissueを立ててください。",
