"modal_and_names.join_the_noc_chat":"NOCチャットに参加",
"modal_and_names.open":"開く →",
"modal_and_names.our_signal_group_screenshots_chat":"私たちのSignalグループ：ほかのプレイヤーとスクリーンショットを見せ合ったり、ピアリングポリシーについて議論したり。本物よりショベルカーは少なめです。",
"modal_and_names.tell_us_on_github_a_short":"GitHubで教えてください。バグ報告、機能のアイデア、バランス、翻訳のための短いフォームがあります。すべて目を通します。",
"modal_and_names.the_real_thing_by_thomas_kj":"本物はこちら。Thomas Kjær Aaboによる、パケットが実際にどう旅するかを示すズーム可能なインタラクティブマップです。Wi-Fiから海底ファイバーまで、現在・2010年・1995年の姿を見られます。このゲームは即興で作っていますが、あちらは正確です。",
"modal_and_names.the_real_thing_follow_a_packet":"本物はこちら：Wi-Fiから海底ファイバーまでパケットを追いかけよう。",
"modals.lay_your_own_subsea_cable":"自前の海底ケーブルを敷設…",
"modals.your_own_subsea_cable_level_n":"自前の海底ケーブル <small>レベル{n}またはTier 1</small>",
"mphelp.boards_rank_traffic_with_players":"ランキングボードは、ほかのプレイヤーとのトラフィック、総トラフィック、POP数、空のパイ、カスタマーコーンを直近24時間の合計または伸びで順位付けします。お金は対象外です。順位付けはあなたのサーバーが行い、あなたのゲームがときどき行を抜き打ちチェックします。人間とAIプレイヤーは一緒にも別々にも表示でき、リージョン、本拠地の市場、ネットワークの年齢などで絞り込めます。",
"mphelp.deals":"取引",
"mphelp.deals_are_sealed_for_the":"取引はすべて当事者の2人だけに封印されています。サーバーは取引を運びますが中身は読めません。何が提示されたかも、価格も、断った理由も。公開されるのは、誰でも参加できるコンソーシアムのプロジェクトだけです。",
"mphelp.for_their_first_30_days":"新規参入者は最初の30日間、既存ネットワークから25%引きで購入できます。新規参入者と取引した既存ネットワークは、その新規参入者が成長したとき（POP 10か所、Tier 2、または自前のトランジット顧客の獲得）に一度だけメンターボーナスを得ます。",
"mphelp.how_multiplayer_works":"Multimodeの仕組み",
"mphelp.joining":"参加する",
"mphelp.multiplayer_puts_other_people_s":"Multimodeは、ほかの人のネットワークをあなたのゲームに持ち込みます。それでも各自が自分のデバイスで自分のゲームを遊びます。サーバーはゲーム同士の間で署名付きのメモを受け渡すだけです。セーブごとの設定で、完全に任意です。",
"mphelp.mute_a_network_and_it":"ネットワークをミュートすると、あなたのゲームからだけ消えます。報告すると、あなたのサーバーの運営者が確認します。運営者は自分のサーバーでネットワークを非表示にでき、十分な数のサーバーが除外に投票すると、そのネットワークはどこでも除外されます。投票は非公開で、見えるのは誰が除外されたかだけ。自分が除外された場合はその理由も見られます。あなたのゲームはいつでも続けられます。",
"mphelp.muting_reporting_and_exclusion":"ミュート、報告、除外",
"mphelp.newcomers_and_mentors":"新規参入者とメンター",
"mphelp.nothing_breaks_your_game_plays":"何も壊れません。ゲームは続き、あなたの操作はキューで待って後から送られ、進行中の取引も維持されます。沈黙したままのネットワークはゆっくりと消えていきます。1週間後にはトラフィックがほかの経路に流れ始め、約5週間後には通知とともに取引が終了します。突然の請求は決してありません。",
"mphelp.peer_with_other_players":"ほかのプレイヤーのネットワークは、あなたの顧客が届きたい場所です。ピアリングしましょう。相手が登録しているIXでも可能です。トランジット、PNI、IXポート、波長を買ったり、容量を交換したり、一緒にコンソーシアムケーブルを建設したりもできます。各ネットワークはポリシーと価格を公開しており、条件を満たすリクエストは、相手が不在でも自動で承認されることがあります。お金がセーブ間を移動することはありません。各ゲームが自分の側を記帳します。",
"mphelp.private_deals":"取引は非公開",
"mphelp.servers_and_operators":"サーバーと運営者",
"mphelp.servers_are_run_by_players":"サーバーはプレイヤーが運営しており、それぞれに1人以上の運営者がいます。誰でも立てられます。ほかのサーバーと同期するサーバーもあり、自分のサーバー外のプレイヤーとも出会えます。ルッキンググラスには、あなたのゲームが知っているすべてのサーバーと同期の様子が表示されます。参加できるのは最大4つまでです。",
"mphelp.switch_on_play_with_others":"タイトル画面で新しいゲームを始めるときに<b>他のプレイヤーと遊ぶ</b>をオンにするか、あとからメニューや設定のMultimodeで参加できます。パズル、シナリオ、サンドボックス、オープンゲートはシングルプレイのままです。ネットワーク名は参加するすべてのサーバーで公開されるので、本名は使わない方が安心です。",
"mphelp.when_a_server_is_down":"サーバーがダウンしたとき",
"mphelp.your_multiplayer_identity_is_a":"ネットワークのMultimode IDは、このセーブに保存された秘密鍵です。Multimodeシートの<b>別のデバイスに移す</b>で、それを含むファイルを1つダウンロードできます。そのファイルを持つ人は誰でもあなたのネットワークになりすませるので、絶対に共有したりバグ報告に添付したりしないでください。エクスポートや共有セーブには鍵は含まれません。",
