"ops.no_cap":"上限なし",
"ops.no_clock":"時計がなければシフトもありません：このルールにはインターンが働く日がありません。",
"ops.o_caches":"無料キャッシュを受け入れる",
"ops.o_caches_d":"その都市でのトラフィックがしきい値を超えたら、ネットワークが提供する無料キャッシュをすべてラックに設置します。",
"ops.o_decom":"小さな並行リンクを廃止",
"ops.o_decom_d":"2都市間により大きなリンクが開通したら、不要になった小さな波長を返却します。顧客が借りているものや頼っているものは決して返しません。",
"ops.o_fabric":"IXを成長させる",
"ops.o_fabric_d":"運営しているIXのトラフィックが「余裕」を超えたとき、または席がすべて埋まって参加待ちのネットワークがいるとき、そのファブリックを増強します。大きなファブリックはより多くのトラフィックを運び、より多くの有料メンバーを受け入れられます。",
"ops.o_ix":"すべてのIXでピアリング",
"ops.o_ix_d":"毎週：ルートサーバーに参加し、各IXポートで応じてくれそうなメンバー全員に申し込みます。",
"ops.o_optics":"ファイバーをもっと点灯",
"ops.o_optics_d":"混雑しているダークファイバーに光モジュールを追加し、新しいファイバーは引き渡されたその日に点灯します。",
"ops.o_optup":"光伝送をアップグレード",
"ops.o_optup_d":"満杯で混雑しているファイバー、または容量市場の買い手が売れる以上に欲しがっているファイバーでは、ラインシステムを1サイズ上げるか、最小のチャネルをより大きな光モジュールに置き換えます（古いものは棚へ）。ラインシステムを選ぶと、それより小さいラインシステムのファイバーはすべてそれに移行します。ラインシステムの交換ではファイバーが1日止まるので、トラフィックが迂回でき、顧客が使っていない場所でのみ、一晩に1本ずつ行います。",
"ops.o_pie":"クラストを満タンに保つ",
"ops.o_pie_d":"古いパイが劣化してもクラストが満タンのままになるよう、打ち上げを予約します。パイは工場の在庫から、発射台は最初に空いたものを使い、試験飛行は使いません。費用はそれぞれ「クラスト」タブの料金と同じです。",
"ops.o_pni":"大手とPNI",
"ops.o_pni_d":"毎週：自分のPOPで十分なトラフィックを送ってくる、応じてくれそうなすべてのネットワークとPNIを、各ネットワークの最小サイズで発注します。",
"ops.o_ports":"ピアリングに余裕を持たせる",
"ops.o_ports_d":"PNIとIXのポートを今日のトラフィックの一定倍以上に保ちます。複数のルーターがあるPOPの単独ポートにはLAGで2本目を追加し、それ以外はポートサイズを1段上げます。",
"ops.o_repair":"緊急修理",
"ops.o_repair_d":"予算が続く限り、緊急修理ができる障害にはすべて費用を払って急がせます。",
"ops.o_routers":"ルーターを先回りで強化",
"ops.o_routers_desc":"負荷やポート数が一定レベルを超えたら、ルーターを追加するか、2台目のルーターがトラフィックを運べる場所では次世代に交換します。モデルを選ぶと、それより小さいモデルのPOPはすべて、予算の範囲内で混んでいる順にそのモデルへ交換されます。",
