"pops_transit_ix.no_transit_in_this_scenario_peering":"<b>このシナリオにトランジットはありません。</b><br>使えるのはピアリング、PNI、キャッシュ、自前のファイバーだけです。",
"pops_transit_ix.opted_out_of_name_it_took":"<b>{name}をオプトアウトしました。</b><br>クリック4回、アンケート1つ、「お別れは寂しいです」ページを経由しました。",
