"pops_transit_ix.remote_port_up_at_ix_it":"<b>{ix}のリモートポートが開通しました。</b><br>リセラー経由なので、上乗せ料金、混雑したポート、相手にしてくれないネットワークは覚悟してください。ここではルートサーバーが頼りになります。",
