"pops_transit_ix.router_installed_in_city_the_vendor":"<b>{city}にルーターを設置しました。</b><br>ベンダーが正しい向きで出荷したので、現地の技術者がひっくり返しました。ここでは他のものもみんな逆さまです。",
"pops_transit_ix.router_installed_in_city_upside_down":"<b>{city}にルーターを設置しました。</b><br>南半球の慣習どおり、逆さまに。パケットは気にしていないようです。",
"pops_transit_ix.signed_with_de_kicks_welcome_to":"<b>DE-KICKSと契約しました。</b><br>ファミリーへようこそ。いくら払っているかは誰にも言わないでくださいね。",
