"pops_transit_ix.this_pni_already_bundles_n_ports":"<b>このPNIはすでに{n}ポートを束ねています</b>。ここのルーターで収容できる上限です。ルーター1台につきPNIのメンバーは{more}本、最大{max}本まで：さらに増やすにはルーターを追加してください。",
