"privacy.ip_addresses_or_anything_finer":"IPアドレス、国より細かい位置情報、デバイス・ブラウザ・タイムゾーン。サーバーは接続元アドレスをメモリ上でのみ使い、国を調べたり大量アクセスを止めたりするだけで、記録は一切しません。登録済みのサーバーは、手前の機器でもアドレスを記録しないことを約束しています。",
"privacy.leave_a_server_and_your":"サーバーから<b>退出</b>すると、ゲームはそのサーバーとの通信をやめ、保存されていた情報は180日以内に消えていきます。<b>完全に退出する</b>と、すべてのサーバーにネットワークの記録を即座に削除するよう伝える「お別れ」に署名し（拡散のため、お別れ自体だけは180日残ります）、このセーブはMultimode IDを忘れます。セーブを削除すると、このデバイスからも消えます。",
"privacy.leaving":"退出",
"privacy.no_account_no_email_no":"アカウントなし、メールアドレスなし、Cookieなし。ゲームが保存するもの、デバイスから送信されるものをすべてここに記載しています。",
"privacy.on_seriesoftub_es_the_page":"seriesoftub.esでは、ページが小さな訪問カウンターを読み込みます（jsDelivrから配信、stats.seriesoftub.esに報告）。ページの閲覧を、ページのアドレス、参照元ページ、ウィンドウ幅、ページを開いていた時間、そしてゲーム内のいくつかの瞬間の名前（新しいゲームの開始やバッジ獲得など）とともにカウントします。Cookieは使わず、ブラウザには何も保存しません。このカウンターはゲームの作者が作ったridiculyticsで、自前のサーバーで動いています：データベースなし、ディスクへの書き込みなし、メモリ上の集計値だけ（ページ別、参照元サイトのホスト名、国、ブラウザ、OS、デバイスの種類、画面サイズの区分、ゲーム内の瞬間）。IPアドレスは訪問のカウント中に国を調べるためだけに使われ、保存も記録もされません。ユニーク訪問者は24時間ごとに秘密値が変わるハッシュで数えるため、日をまたいで訪問を結びつけることはできません。他の場所にあるゲームのコピーは何も送信しません。",
"privacy.on_this_device":"このデバイス上",
"privacy.the_same_on_the_web":"Web版のこのページ",
"privacy.the_visit_counter":"訪問カウンター",
"privacy.traffic_numbers_for_72_hours":"トラフィックの数値は72時間（と最新の値）、取引は30日、ネットワークの説明は180日間音沙汰がなくなるまで。時刻は5分単位に丸められます。ネットワークに対するオペレーターの投票は97日間残ります。",
"privacy.what_servers_keep":"サーバーが保存するもの",
"privacy.what_servers_never_keep":"サーバーが決して保存しないもの",
"privacy.what_the_game_keeps":"ゲームが保存するもの",
"privacy.what_the_game_keeps_and":"ゲームが保存・送信するもの",
"privacy.when_you_join_a_server":"サーバーに参加したとき",
"privacy.while_you_play":"プレイ中",
"privacy.your_current_numbers_every_10":"現在の数値（上と同じもので、それ以上はなし）を、ゲームを開いていて値が変わった場合に10秒ごとに送信します。これでリーダーボードに今の状況が表示されます。サーバーはこれをメモリ上にだけ保持し、ディスクには書かず、最後の送信から15分で忘れます。",
"privacy.your_game_sends_these_signed_records":"ゲームは次の署名付きレコードを送信します：ネットワークの名前、AS番号、ゲーム内のホーム市場、参加したゲーム内の日と現実の日、POPとIXのある都市、顧客数、トラフィックの数値と内訳、他の各プレイヤーのネットワークと交換しているトラフィック量、Tier 1かTier 2か、公開しているポリシーと価格、トランジットの購入先・販売先（価格は送りません）、そしてAIエージェントがプレイしている場合はそのAIモデルとハーネス。取引は相手プレイヤーだけが読めるよう封をして送られます。他のネットワークについての通報（どのネットワークか、その理由）は、そのサーバーのオペレーターに届きます。<b>自分の国を共有する</b>がオンの間は現実の国も追加され、オフにするまでオンのままです。",
"privacy.your_saves_settings_and_badges":"セーブ、設定、バッジ、進行状況はこのブラウザのストレージに残ります。Multimodeでは、ネットワークの秘密鍵（セーブ内）、サーバーから送られてきた他のネットワークの情報（180日間更新がなければ忘れます）、インポートした場合はオペレーターキーも保存します。サーバーに参加するか自分でセーブを送らない限り、何もアップロードされません。",
