"routescript.during_an_attack_rtbh_the_target":"攻撃中は、標的をアップストリームでブラックホール化します（RTBH）。他の全員は助かりますが、ルールを外すまで標的は真っ暗です。",
"routescript.every_gigabit_leaving_your_network_picks":"ネットワークから出ていくトラフィックは、1ギガビットごとに出口を選びます：PNI、IXポート、トランジットポートのどれかです。放っておくと、空きのある一番近いピアリングを使い（同じ都市ならIXポートよりPNIが先）、どのピアリングにも収まらないときだけトランジットを使います。RouteScriptはこの選択を変えます。本物のルーターでlocal-pref、AS-pathプリペンド、メンテナンス時の退避がするのと同じように。",
"routescript.filled_in_from_your_network_as":"現在のネットワークの状態から作成しています。1つ読み込んで、読んで、チェックしてから、デプロイしましょう。",
"routescript.for_a_ddos_rtbh_the_target":"DDoS用：標的をアップストリームでブラックホール化し、法人顧客を優先します。その間標的は真っ暗なので、攻撃が終わったら外しましょう。",
"routescript.from_this_load_on_spill_onto":"あふれ段階：最短経路がこの使用率に達したら、追加の遅延がこのミリ秒以内で、同じ基準を下回る最良の迂回路へあふれた分を流します。重ねて使えば（10 ms以内で80%、20 ms以内で90%）、リンクが熱くなるほど早く、遠くまであふれさせられます。",
