"sales.auto":"代わりに契約してくれます",
"sales.auto_ceo":"{name}は、今日のネットワークで提供できるオファーに1日1件のトライアルで契約します。最低価格を下回るものも断りますが、ときどきすでに握手を済ませてしまっています。",
