"sales.eng_d":"元ネットワークエンジニアで、今ではどのNOGのネックストラップも持っています。毎回あなたを登録し（チケット代はあなた持ち）、中小規模の取引をたくさん持ってきますが、超大型案件はありません。ネットワークにできることしか売らないので、顧客は離れません。オタクたちはDaveが大好き。値引き交渉は苦手です。",
