"scenarios.amsterdam_hosting_capital_of_europe":"ヨーロッパのホスティングの都、アムステルダム。時はボットネットの最盛期。地球上のスマートトースター、ベビーモニター、パッチの当たっていない冷蔵庫がこぞって陣営を選び、それはあなたの側ではありません。数日おきに攻撃の洪水が押し寄せ、テラビット級も増える一方。その間にも他のものは壊れ続けます。最初から大型機材が解放されています。必要になりますよ。",
"scenarios.broadband_in_sydney_melbourne_served":"シドニー、メルボルン、ブリスベン、アデレード、パースでブロードバンドを提供し、海外への異なる2本のケーブルを持ち、500 Gbpsを配信",
"scenarios.cape_to_cairo":"ケープからカイロへ",
"scenarios.cape_town_build_a_network_across":"ケープタウン。アフリカを横断するネットワークを築きましょう。国境ごとに独自の許可が必要で、発電機もネットワークの一部です。",
"scenarios.cogentle_and_goggle_are_not_speaking":"CogentleとGoggleは口をきいていません。今回は永遠に。勇気があるなら安いトランジットを買ってみましょう。",
