"scenarios.every_cable_through_the_red_sea":"紅海を通るケーブルはすべて切断され、エジプトへのホップも切れています。それでもマルセイユとシンガポールをつなぎましょう：アフリカを回るか、陸路か、地球の反対側を回るか。",
