"scenarios.honolulu_in_the_middle_of_the":"太平洋のど真ん中、ホノルル。南北アメリカ、アジア、オーストラリアを結ぶケーブルはとても長く、1波長で400Gか800Gしか運べません。島で光を止めて新たに送り出せば、どのホップも短く速くなります。最初から1.6T機材が解放されています。",
