"scenarios.only_spatzle_ix":"Spätzle-IXのみ",
"scenarios.order_and_progress":"秩序と進歩",
"scenarios.ponta_delgada_azores_lisbon_lagos":"大西洋の中間、アゾレス諸島のポンタ・デルガダ。フロリダからスペインは1.6Tの波長には遠すぎて、直通だと1.2Tしか運べません。途中の島々に陸揚げして光を新たに送り出せば、どのホップも1.6T以上で走ります。リスボンからラゴスは一気に1.6Tで行けますが、お値段は張ります：カナリア諸島経由の方が安上がりです。最初から1.6T機材が解放されています。",
"scenarios.ports_on_15_ix_brrr_exchanges_backbone":"バックボーンをサンパウロとつないだ15か所のIX.brrrエクスチェンジにポートを持ち（うち1か所はマナウス）、200 Gbpsを配信",
