"scenarios.sandbox_mode_a_billion_dollars_chaos":"<b>サンドボックスモード</b><br>10億ドルと全解放。カオス：{chaos}。ずっと欲しかったインターネットを作りましょう。予備のショベルカーもお忘れなく。",
"scenarios.sandbox_mode_a_billion_dollars_every":"<b>サンドボックスモード</b><br>10億ドル、全解放、そして何も壊れません。ずっと欲しかったインターネットを作りましょう。",
"scenarios.sao_paulo_brazil_is_a_continent":"サンパウロ。ブラジルはひとつの大陸です：40か所のIX.brrrエクスチェンジ、何千もの地域プロバイダー（provedores）、そして北との間にはアマゾン。",
"scenarios.seoul_sender_pays_d":"送信側負担のソウル。キャリアが韓国に届けるトラフィック1 Gbpsごとに、トランジット料金に加えて送信側負担の料金がかかります。老舗3社は有料PNIでしか接続せず、家庭用ギガビットはビビンバ1杯分の値段で売られ、韓国のユーザーは1ミリ秒の差も見逃しません。東京のトランジットは安いですが、顧客がその遠回りに耐えられれば、の話です。",
"scenarios.seoul_sender_pays_goal":"{g} Gbpsを配信、ソウルで高品質（{q}%）、到達率99%、月次黒字",
"scenarios.shark_season_subsea_cuts_twice_as":"サメの季節：海底ケーブル切断が2倍",
"scenarios.start_in_panama_city_nothing_crosses":"パナマシティからスタート。ダリエン地峡を陸路で越えるものはなく、それ以外の道にはすべてアンデス山脈が立ちはだかります。",
"scenarios.start_in_stuttgart_where_nobody":"トランジットを誰も売っていないシュトゥットガルトからスタート。ピアリング、PNI、キャッシュ、自前の光ファイバーだけでインターネットに到達しましょう。トランジットはどこにも、永遠にありません。",
"scenarios.start_with_only_100k":"$100kだけでスタート",
"scenarios.sydney_2013_the_toilet_paper_group":"2013年のシドニー。Toilet Paper Groupはマンションの地下室まで自前の光ファイバーを引き込み、国のネットワークは「いいとこ取りだ」と泣きつきました。今度はあなたの番：Nearly Broadband Networkを飛ばし、負担金を払って、一番乗りしましょう。",
"scenarios.tallinn_nobody_sells_transit_anchors":"トランジットを誰も売っていないタリン：インターネットは海の向こうです。バルト海のケーブルを船が錨で引きずる頻度は、通常の3倍です。",
